import type { EnderecoSugestao } from './types';

/**
 * Base local de CEPs de São Paulo capital + região metropolitana (Guarulhos,
 * Osasco, Santo André, São Bernardo do Campo, Diadema, Barueri). Amostra variada
 * (~500 CEPs) coletada via ViaCEP, cobrindo o Centro e as zonas Norte/Sul/Leste/
 * Oeste.
 *
 * Uso: autocomplete de CEP parcial na tela de endereço — a partir de 4 dígitos
 * sugerimos CEPs que começam com a sequência digitada, sem bater na rede. Se o
 * CEP não estiver aqui, o fluxo cai no ViaCEP ao completar os 8 dígitos.
 *
 * Ordenada por CEP crescente (o filtro preserva a ordem).
 */
export type CepLocal = {
  cep: string;
  logradouro: string;
  bairro: string;
  cidade: string;
  uf: string;
};

const onlyDigits = (value: string) => value.replace(/\D/g, '');

