/** Sugestões locais cujo CEP começa com os dígitos informados (>= 4). Ordem: CEP crescente. */
export function buscarCepsLocais(input: string, limit = 50): CepLocal[] {
  const digits = onlyDigits(input);
  if (digits.length < 4) return [];
  const matches: CepLocal[] = [];
  for (const item of CEPS_SP) {
    if (onlyDigits(item.cep).startsWith(digits)) {
      matches.push(item);
      if (matches.length >= limit) break;
    }
  }
  return matches;
}

/** Match exato de um CEP completo (8 dígitos) na base local. */
export function acharCepExato(input: string): CepLocal | null {
  const digits = onlyDigits(input);
  if (digits.length !== 8) return null;
  return CEPS_SP.find((item) => onlyDigits(item.cep) === digits) ?? null;
}

/** Linha exibida no dropdown: "00000-000 - Rua X, Bairro, Cidade/UF". */
export function formatCepLocalLinha(item: CepLocal): string {
  const local = [item.bairro, [item.cidade, item.uf].filter(Boolean).join('/')]
    .filter(Boolean)
    .join(', ');
  return [item.cep, [item.logradouro, local].filter(Boolean).join(', ')]
    .filter(Boolean)
    .join(' - ');
}

/** Converte um CEP local pro mesmo shape do autocomplete (Nominatim/ViaCEP). */
export function cepLocalParaSugestao(item: CepLocal): EnderecoSugestao {
  return {
    place_id: Number(onlyDigits(item.cep)) || 0,
    display_name: [item.logradouro, item.bairro, item.cidade, item.uf].filter(Boolean).join(', '),
    address: {
      road: item.logradouro || undefined,
      house_number: null,
      suburb: item.bairro || undefined,
      city: item.cidade || undefined,
      state: item.uf || undefined,
      postcode: item.cep || undefined,
    },
  };
}
